import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total = scanner.nextInt();
        int maxCost = scanner.nextInt();
        int[] values = new int[total];
        for (int index = 0; index < total; index++) {
            values[index] = scanner.nextInt();
        }
        System.out.println(calculateMaxSegments(values, maxCost));
    }

    private static int calculateMaxSegments(int[] array, int maxBudget) {
        ArrayList<Integer> differences = new ArrayList<>();
        int evenCount = array[0] % 2 == 0 ? 1 : 0;
        int oddCount = array[0] % 2 == 1 ? 1 : 0;
        int countSegments = 0;
        for (int i = 1; i < array.length; i++) {
            if (oddCount == evenCount && Math.abs(array[i] - array[i - 1]) <= maxBudget) {
                evenCount = 0;
                oddCount = 0;
                differences.add(Math.abs(array[i] - array[i - 1]));
            }
            if (array[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        Collections.sort(differences);
        for (int diff : differences) {
            if (maxBudget < diff) {
                break;
            }
            countSegments++;
            maxBudget -= diff;
        }
        return countSegments;
    }
}
