#include <iostream>
#include <vector>
#include <algorithm>

int calculateMaxSegments(const std::vector<int>& array, int maxBudget) {
    std::vector<int> differences;
    int evenCount = (array[0] % 2 == 0) ? 1 : 0;
    int oddCount = (array[0] % 2 == 1) ? 1 : 0;
    int countSegments = 0;
    for (size_t i = 1; i < array.size(); ++i) {
        if (oddCount == evenCount && std::abs(array[i] - array[i - 1]) <= maxBudget) {
            evenCount = 0;
            oddCount = 0;
            differences.push_back(std::abs(array[i] - array[i - 1]));
        }
        if (array[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }
    std::sort(differences.begin(), differences.end());
    for (int diff : differences) {
        if (maxBudget < diff) {
            break;
        }
        ++countSegments;
        maxBudget -= diff;
    }
    return countSegments;
}

int main() {
    int total, maxCost;
    std::cin >> total >> maxCost;
    std::vector<int> values(total);
    for (int i = 0; i < total; ++i) {
        std::cin >> values[i];
    }
    std::cout << calculateMaxSegments(values, maxCost) << std::endl;
    return 0;
}
